def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Build quick views
    op = [h[1] for h in history]
    me = [h[0] for h in history]

    last_op = op[-1]
    last_me = me[-1]

    # Count totals
    op_def = 0
    my_def = 0
    op_c = 0
    for a in op:
        if a == 'D':
            op_def += 1
        else:
            op_c += 1
    for a in me:
        if a == 'D':
            my_def += 1

    # Recent window (last 8)
    w = 8
    if n < w:
        w = n
    recent_op_def = 0
    recent_op_c = 0
    recent_my_c = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            recent_op_def += 1
        else:
            recent_op_c += 1
        if me[i] == 'C':
            recent_my_c += 1

    # Defection streak of opponent
    op_def_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            op_def_run += 1
        else:
            break

    # Mutual defection run
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and op[i] == 'D':
            dd_run += 1
        else:
            break

    # Opponent cooperation run
    op_c_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            op_c_run += 1
        else:
            break

    rounds_left = 100 - n
    op_coop_rate = op_c / n

    # Endgame exploitation: against a clearly cooperative partner, defect last 2 rounds
    if rounds_left <= 2:
        if op_def_run <= 1 and op_c_run >= 2:
            return 'D'
        if last_op == 'D' and last_me == 'D':
            return 'D'
        if op_coop_rate >= 0.7:
            return 'D'
        return 'D'

    # Pure cooperator: exploit only at very end, otherwise cooperate
    if op_def == 0:
        if rounds_left <= 2:
            return 'D'
        return 'C'

    # If we are stuck in DD loop, occasionally attempt conciliatory C to restart
    if dd_run >= 2:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_op == 'D':
        # Isolated defection: forgive once and re-cooperate
        if op_def_run == 1 and op_def <= 2 and op_c_run == 0 and n >= 3:
            if recent_my_c >= 2 and rng.random() < 0.7:
                return 'C'
            return 'D'

        # Persistent defector over recent window: keep defecting but test for peace
        if recent_op_def >= 5:
            if rng.random() < 0.08:
                return 'C'
            return 'D'

        # Moderate defector: retaliate once, then likely return to C
        if op_def_run == 1:
            return 'D'
        if op_def_run == 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Longer streak: defect with rare conciliation
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just cooperated
    # If opponent is heavily defective overall, don't get lulled: sometimes defect
    if op_def * 2 > n:
        if recent_op_def >= 3:
            return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent largely cooperative
    if op_coop_rate >= 0.85:
        # Very rare early probe to test for exploitability
        if n >= 20 and n <= 80 and op_def_run == 0 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Opponent moderately cooperative: TFT with forgiveness
    if op_coop_rate >= 0.55:
        if op_def_run == 0:
            if n >= 20 and rng.random() < 0.04:
                return 'D'
            return 'C'
        # Opponent had recent defections but just cooperated: continue cooperating to repair
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    # Opponent mostly defecting: defend, but occasionally reconcile
    if recent_op_def >= 4:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    if rng.random() < 0.15:
        return 'C'
    return 'D'
